const listUnknownOperations = `-- name: ListUnknownOperations :many
SELECT id, tenant_id, charge_id, refund_id, kind, status, external_reference, attempts, lease_until, next_attempt_at, last_error, provider_response, created_at, updated_at, completed_at FROM payment_operations
 WHERE tenant_id = $1
   AND (status = 'unknown' OR (status = 'in_flight' AND (lease_until IS NULL OR lease_until < $2)))
 ORDER BY created_at, id LIMIT $3
`

type ListUnknownOperationsParams struct {
	TenantID uuid.UUID
	Now      *time.Time
	RowLimit int32
}

// Operações com resultado desconhecido: situação unknown ou em execução com o
// lease expirado (processo interrompido durante a chamada ao provedor).
func (q *Queries) ListUnknownOperations(ctx context.Context, arg ListUnknownOperationsParams) ([]PaymentOperation, error) {
	rows, err := q.db.Query(ctx, listUnknownOperations, arg.TenantID, arg.Now, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PaymentOperation
	for rows.Next() {
		var i PaymentOperation
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.ChargeID,
			&i.RefundID,
			&i.Kind,
			&i.Status,
			&i.ExternalReference,
			&i.Attempts,
			&i.LeaseUntil,
			&i.NextAttemptAt,
			&i.LastError,
			&i.ProviderResponse,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CompletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockChargeRefundClaims = `-- name: LockChargeRefundClaims :exec
SELECT pg_advisory_xact_lock(hashtextextended(concat('refund_claim:', $1::uuid, ':', $2::uuid), 0))
`

type LockChargeRefundClaimsParams struct {
	TenantID uuid.UUID
	ChargeID uuid.UUID
}

// Bloqueio consultivo até o fim da transação: serializa a reivindicação das
// operações de reembolso de uma cobrança sem bloquear a linha da cobrança.
func (q *Queries) LockChargeRefundClaims(ctx context.Context, arg LockChargeRefundClaimsParams) error {
	_, err := q.db.Exec(ctx, lockChargeRefundClaims, arg.TenantID, arg.ChargeID)
	return err
}

const markChargesReconciled = `-- name: MarkChargesReconciled :exec
INSERT INTO reconciliation_charge_checks (tenant_id, charge_id, last_checked_at)
SELECT $1::uuid, id, $2::timestamptz FROM unnest($3::uuid[]) AS id
ON CONFLICT (tenant_id, charge_id) DO UPDATE SET last_checked_at = excluded.last_checked_at
`

type MarkChargesReconciledParams struct {
	TenantID  uuid.UUID
	CheckedAt time.Time
	ChargeIds []uuid.UUID
}

// Registra a verificação das cobranças comparadas numa execução concluída.
func (q *Queries) MarkChargesReconciled(ctx context.Context, arg MarkChargesReconciledParams) error {
	_, err := q.db.Exec(ctx, markChargesReconciled, arg.TenantID, arg.CheckedAt, arg.ChargeIds)
	return err
}

